<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';
$user=require_role('admin');
$error='';
function valid_new_password(string $password):bool{return strlen($password)>=12;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verify_csrf(isset($_POST['csrf_token'])?(string)$_POST['csrf_token']:null)){http_response_code(400);exit('Invalid request token. Reload and try again.');}
 $action=(string)($_POST['action']??'');
 if($action==='create'){
  $username=trim((string)($_POST['username']??''));$display=trim((string)($_POST['display_name']??''));$employee=trim((string)($_POST['employee_number']??''));$email=trim((string)($_POST['email']??''));$role=(string)($_POST['role']??'employee');$permissions=array_values(array_intersect((array)($_POST['permissions']??[]),['bidder','power_user','procurement','custodian','approver']));$password=(string)($_POST['password']??'');
  if(!preg_match('/^[A-Za-z0-9._-]{3,80}$/',$username))$error='Username must be 3–80 characters using letters, numbers, dots, underscores or hyphens.';
  elseif($display===''||mb_strlen($display)>160)$error='Enter a display name of 1–160 characters.';
  elseif(mb_strlen($employee)>80)$error='Employee number is too long.';
  elseif($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Enter a valid email address or leave it blank.';
  elseif(strlen($email)>254)$error='Email address is too long.';
  elseif(!in_array($role,['employee','admin','auditor'],true))$error='Choose a valid role.';
  elseif(!valid_new_password($password))$error='Initial password must be at least 12 characters.';
  else{
   try{$q=db()->prepare('INSERT INTO users(username,display_name,employee_number,email,password_hash,role,status) VALUES(:username,:display,:employee,:email,:hash,:role,\'active\')');$q->execute(['username'=>$username,'display'=>$display,'employee'=>$employee!==''?$employee:null,'email'=>$email!==''?$email:null,'hash'=>password_hash($password,PASSWORD_DEFAULT),'role'=>$role]);$id=(int)db()->lastInsertId();save_user_permissions($id,$permissions,(int)$user['id']);audit_log((int)$user['id'],'user.created','user',(string)$id,['username'=>$username,'role'=>$role]);redirect_to('admin/users.php?created=1');}
   catch(PDOException $ex){if(str_contains(strtolower($ex->getMessage()),'unique'))$error='That username, employee number or email address is already in use.';else throw $ex;}
  }
 }elseif($action==='update_user'){
  $id=(int)($_POST['user_id']??0);$display=trim((string)($_POST['display_name']??''));$employee=trim((string)($_POST['employee_number']??''));$email=trim((string)($_POST['email']??''));$role=(string)($_POST['role']??'employee');$permissions=array_values(array_intersect((array)($_POST['permissions']??[]),['bidder','power_user','procurement','custodian','approver']));
  $targetQ=db()->prepare('SELECT id,role,status FROM users WHERE id=:id');$targetQ->execute(['id'=>$id]);$target=$targetQ->fetch();
  if(!$target)$error='User account not found.';
  elseif($id===(int)$user['id']&&$role!=='admin')$error='You cannot remove administrator access from your own account.';
  elseif($display===''||mb_strlen($display)>160)$error='Enter a display name of 1–160 characters.';
  elseif(mb_strlen($employee)>80)$error='Employee number is too long.';
  elseif($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Enter a valid email address or leave it blank.';
  elseif(strlen($email)>254)$error='Email address is too long.';
  elseif(!in_array($role,['employee','admin','auditor'],true))$error='Choose a valid role.';
  else{
   $activeAdmins=(int)db()->query("SELECT COUNT(*) FROM users WHERE role='admin' AND status='active'")->fetchColumn();
   if($target['role']==='admin'&&$target['status']==='active'&&$role!=='admin'&&$activeAdmins<=1)$error='You cannot remove the last active administrator.';
   else{try{$q=db()->prepare('UPDATE users SET display_name=:display,employee_number=:employee,email=:email,role=:role,updated_at=datetime(\'now\') WHERE id=:id');$q->execute(['display'=>$display,'employee'=>$employee!==''?$employee:null,'email'=>$email!==''?$email:null,'role'=>$role,'id'=>$id]);save_user_permissions($id,$permissions,(int)$user['id']);audit_log((int)$user['id'],'user.details_updated','user',(string)$id,['role'=>$role,'permissions'=>$permissions]);redirect_to('admin/users.php?updated=1');}catch(PDOException $ex){if(str_contains(strtolower($ex->getMessage()),'unique'))$error='That employee number or email address is already assigned to another account.';else throw $ex;}}
  }
 }elseif($action==='update_email'){
  $email=trim((string)($_POST['email']??''));
  if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Enter a valid email address or leave it blank.';
  elseif(strlen($email)>254)$error='Email address is too long.';
  else{try{$q=db()->prepare("UPDATE users SET email=:email,updated_at=datetime('now') WHERE id=:id");$q->execute(['email'=>$email!==''?$email:null,'id'=>(int)$user['id']]);audit_log((int)$user['id'],'user.email_updated','user',(string)$user['id']);redirect_to('admin/users.php?email_updated=1');}catch(PDOException $ex){if(str_contains(strtolower($ex->getMessage()),'unique'))$error='That email address is already assigned to another account.';else throw $ex;}}
 }elseif($action==='status'){
  $id=(int)($_POST['user_id']??0);$status=(string)($_POST['status']??'');
  $targetQ=db()->prepare('SELECT id,role,status FROM users WHERE id=:id');$targetQ->execute(['id'=>$id]);$target=$targetQ->fetch();
  if($id===(int)$user['id'])$error='You cannot disable your own account.';
  elseif(!$target)$error='User account not found.';
  elseif(!in_array($status,['active','disabled'],true))$error='Invalid account status.';
  elseif($status==='disabled'&&$target['role']==='admin'&&$target['status']==='active'&&(int)db()->query("SELECT COUNT(*) FROM users WHERE role='admin' AND status='active'")->fetchColumn()<=1)$error='You cannot disable the last active administrator.';
  else{$q=db()->prepare('UPDATE users SET status=:status,updated_at=datetime(\'now\') WHERE id=:id');$q->execute(['status'=>$status,'id'=>$id]);if($q->rowCount())audit_log((int)$user['id'],'user.status_changed','user',(string)$id,['status'=>$status]);redirect_to('admin/users.php?updated=1');}
 }elseif($action==='reset_password'){
  $id=(int)($_POST['user_id']??0);$password=(string)($_POST['password']??'');
  if(!valid_new_password($password))$error='New password must be at least 12 characters.';
  else{
   $pdo=db();$pdo->beginTransaction();
   try{
    $q=$pdo->prepare('UPDATE users SET password_hash=:hash,updated_at=datetime(\'now\') WHERE id=:id');
    $q->execute(['hash'=>password_hash($password,PASSWORD_DEFAULT),'id'=>$id]);
    if($q->rowCount()===0){$pdo->rollBack();$error='User account not found.';}
    else{
     $q=$pdo->prepare("UPDATE password_reset_tokens SET used_at=datetime('now') WHERE user_id=:id AND used_at IS NULL");$q->execute(['id'=>$id]);
     $pdo->commit();audit_log((int)$user['id'],'user.password_reset','user',(string)$id);redirect_to('admin/users.php?reset=1');
    }
   }catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();throw $ex;}
  }
 }
}
$users=db()->query('SELECT id,username,display_name,employee_number,email,role,status,created_at,last_login_at FROM users ORDER BY display_name COLLATE NOCASE,id')->fetchAll();
require dirname(__DIR__,2).'/app/layout.php';render_page_start('User management','users',$user);
?>
