<?php if(isset($_GET['created'])): ?><div class="notice"><span class="notice-dot"></span><div><strong>User created</strong><p>The account is ready for its first sign-in.</p></div></div><?php endif; ?><?php if(isset($_GET['updated'])): ?><div class="notice"><span class="notice-dot"></span><div><strong>Account updated</strong></div></div><?php endif; ?><?php if(isset($_GET['email_updated'])): ?><div class="notice"><span class="notice-dot"></span><div><strong>Email address updated</strong></div></div><?php endif; ?><?php if(isset($_GET['reset'])): ?><div class="notice"><span class="notice-dot"></span><div><strong>Password reset</strong><p>Share the new temporary password with the employee securely.</p></div></div><?php endif; ?><?php if($error!==''): ?><div class="alert" role="alert"><?= e($error) ?></div><?php endif; ?>
<section class="content-panel"><div class="section-heading"><div><p class="eyebrow">BULK IMPORT</p><h2>Creating several accounts?</h2><p class="muted">Import a CSV file instead of entering every account individually.</p></div><a class="button button-secondary" href="<?= e(app_url('admin/bulk-users.php')) ?>">Bulk user upload →</a></div></section><section class="content-panel"><div class="section-heading"><div><p class="eyebrow">NEW ACCOUNT</p><h2>Create a staff login</h2></div></div><form method="post" class="admin-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="create"><div class="form-grid"><div><label for="username">Username</label><input id="username" name="username" required maxlength="80" pattern="[A-Za-z0-9._-]{3,80}"></div><div><label for="display_name">Display name</label><input id="display_name" name="display_name" required maxlength="160"></div><div><label for="employee_number">Employee number <span class="muted">(optional)</span></label><input id="employee_number" name="employee_number" maxlength="80"></div><div><label for="email">Email address <span class="muted">(required for self-service password reset)</span></label><input id="email" name="email" type="email" maxlength="254" autocomplete="email"></div><div><label for="role">Access role</label><select id="role" name="role"><option value="employee">Bidder / employee</option><option value="auditor">Auditor — read-only audit access</option><option value="admin">Administrator</option></select></div></div><fieldset class="permission-fieldset"><legend>Additional permissions</legend><div class="permission-grid"><label><input type="checkbox" name="permissions[]" value="bidder" checked> Bidder</label><label><input type="checkbox" name="permissions[]" value="procurement"> Procurement</label><label><input type="checkbox" name="permissions[]" value="custodian"> Custodian</label><label><input type="checkbox" name="permissions[]" value="approver"> Line manager / approver</label></div><p class="form-help">An administrator automatically has all permissions. Power users can submit item-change requests; custodians/procurement reviewers and line managers handle the separate review stages. Permissions can be combined on one account.</p></fieldset><label for="password">Initial password</label><input id="password" name="password" type="password" required minlength="12" autocomplete="new-password"><p class="form-help">Use at least 12 characters. The password is hashed before it is stored. Self-service password reset is available when an email address and mail delivery are configured.</p><button class="button button-primary" type="submit">Create account →</button></form></section>
<section class="content-panel"><div class="section-heading"><div><p class="eyebrow">REGISTERED USERS</p><h2>Staff accounts</h2></div><span class="status-pill"><?= count($users) ?> accounts</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Staff member</th><th>Username / employee no.</th><th>Role / permissions</th><th>Status</th><th>Last sign-in</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><strong><?= e($u['display_name']) ?></strong></td><td><?= e($u['username']) ?><small class="table-sub"><?= e($u['employee_number']??'No employee number') ?></small><small class="table-sub"><?= e($u['email']??'No email address') ?></small></td><td><span class="status-pill"><?= e(ucfirst($u['role'])) ?></span><?php foreach(user_permissions((int)$u['id']) as $permission): ?><small class="table-sub"><?= e(ucfirst($permission)) ?></small><?php endforeach; ?></td><td><span class="status-pill"><?= e(ucfirst($u['status'])) ?></span></td><td><?= e($u['last_login_at']??'Never') ?></td><td><?php if((int)$u['id']!==(int)$user['id']): ?><details class="reset-details"><summary>Edit account</summary><form method="post" class="reset-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="update_user"><input type="hidden" name="user_id" value="<?= (int)$u['id'] ?>"><label for="display<?= (int)$u['id'] ?>">Display name</label><input id="display<?= (int)$u['id'] ?>" name="display_name" value="<?= e($u['display_name']) ?>" maxlength="160" required><label for="employee<?= (int)$u['id'] ?>">Employee number</label><input id="employee<?= (int)$u['id'] ?>" name="employee_number" value="<?= e($u['employee_number']??'') ?>" maxlength="80"><label for="email<?= (int)$u['id'] ?>">Email address</label><input id="email<?= (int)$u['id'] ?>" name="email" type="email" value="<?= e($u['email']??'') ?>" maxlength="254" autocomplete="email"><label for="role<?= (int)$u['id'] ?>">Role</label><select id="role<?= (int)$u['id'] ?>" name="role"><option value="employee" <?= $u['role']==='employee'?'selected':'' ?>>Bidder / employee</option><option value="auditor" <?= $u['role']==='auditor'?'selected':'' ?>>Auditor</option><option value="admin" <?= $u['role']==='admin'?'selected':'' ?>>Administrator</option></select><fieldset class="permission-fieldset"><legend>Additional permissions</legend><div class="permission-grid"><?php foreach(['bidder'=>'Bidder','power_user'=>'Power user — request item changes','procurement'=>'Procurement reviewer','custodian'=>'Custodian reviewer','approver'=>'Line manager / approver'] as $perm=>$label): ?><label><input type="checkbox" name="permissions[]" value="<?= e($perm) ?>" <?= in_array($perm,user_permissions((int)$u['id']),true)?'checked':'' ?>> <?= e($label) ?></label><?php endforeach; ?></div><p class="form-help">Power users submit changes; procurement/custodians review first; a different line manager gives final approval.</p></fieldset><button class="button button-quiet" type="submit">Save account</button></form></details><form method="post" class="stacked-action" onsubmit="return confirm('Change this account status?');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="status"><input type="hidden" name="user_id" value="<?= (int)$u['id'] ?>"><input type="hidden" name="status" value="<?= $u['status']==='active'?'disabled':'active' ?>"><button class="button button-quiet" type="submit"><?= $u['status']==='active'?'Disable':'Enable' ?></button></form><details class="reset-details"><summary>Reset password</summary><form method="post" class="reset-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="reset_password"><input type="hidden" name="user_id" value="<?= (int)$u['id'] ?>"><label for="pw<?= (int)$u['id'] ?>">New password</label><input id="pw<?= (int)$u['id'] ?>" name="password" type="password" minlength="12" required autocomplete="new-password"><button class="button button-quiet" type="submit">Set password</button></form></details><?php else: ?><form method="post" class="reset-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="update_email"><label for="self-email">Your email address</label><input id="self-email" name="email" type="email" maxlength="254" value="<?= e($u['email']??'') ?>" autocomplete="email"><button class="button button-quiet" type="submit">Save email</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php render_page_end(); ?>